items = []
for rid, en, es in ITEMS:
    req = rid.split(".")[0]
    items.append({
        "id": f"req.{rid}", "family": req,
        "family_title": {"en": f"Requirement {req} - {REQ[req][0]}",
                         "es": f"Requisito {req} - {REQ[req][1]}"},
        "title": {"en": en, "es": es},
    })
pathlib.Path("crossmap/data/controls_pci.json").write_text(
    json.dumps({"framework": "PCI", "items": items}, ensure_ascii=False, indent=1))
print("PCI DSS:", len(items), "requisitos")
